#include <bits/stdc++.h>
using namespace std;

int main(){
    int n;
    scanf("%d",&n);
    vector<int> p(n);
    for(int i=0;i<n;i++) scanf("%d",&p[i]);

    vector<pair<int,int>> ops;

    auto doOp = [&](int x, int y){
        assert(x>=1 && y>=1 && x+y<n);
        ops.push_back({x,y});
        vector<int> res;
        for(int i=n-y;i<n;i++) res.push_back(p[i]);
        for(int i=x;i<n-y;i++) res.push_back(p[i]);
        for(int i=0;i<x;i++) res.push_back(p[i]);
        p=res;
    };

    // Place elements 1..n-1 into positions 0..n-2
    for(int tgt=0; tgt<n-1; tgt++){
        int pos=-1;
        for(int i=tgt;i<n;i++) if(p[i]==tgt+1){pos=i;break;}
        if(pos==tgt) continue;

        // We need to move element from pos to tgt.
        // Already sorted: positions 0..tgt-1
        // Working range: positions tgt..n-1, length = n-tgt

        // Step 1: Move element to position n-1 if not already there
        if(pos!=n-1){
            // suffix of size (n-1-pos) brings p[pos+1..n-1] to front
            // prefix of size (pos+1) brings p[0..pos] to back, so p[pos] goes to position n-1
            int x=pos+1, y=n-1-pos;
            if(x+y<n){
                doOp(x,y);
            } else {
                // x+y = n, need x+y < n. This happens when middle is empty.
                // Use x=pos, y=n-1-pos if pos>=1
                if(pos>=1){
                    doOp(pos, n-1-pos);
                    // p[pos] is now at position pos (middle of size 1). Find it again.
                    for(int i=tgt;i<n;i++) if(p[i]==tgt+1){pos=i;break;}
                    if(pos==tgt) continue;
                    if(pos!=n-1){
                        int x2=pos+1, y2=n-1-pos;
                        if(x2+y2<n) doOp(x2,y2);
                    }
                }
            }
            for(int i=tgt;i<n;i++) if(p[i]==tgt+1){pos=i;break;}
            if(pos==tgt) continue;
        }

        // Step 2: Element is at position n-1. Move to position tgt.
        // Use x=tgt, y=1 if tgt>=1: brings p[n-1] to pos 0, p[0..tgt-1] to end (bad, messes sorted)
        // Use x=1, y = n-1-tgt: brings p[tgt..n-1] to front. Element at n-1 goes to position n-1-tgt. Not tgt.
        // Better: x=tgt+1, y=1 (if tgt+2<n): result = [p[n-1]][p[tgt+1..n-2]][p[0..tgt]]
        // p[n-1] at pos 0, sorted prefix at end. Not good if tgt>0.
        if(pos==n-1 && pos!=tgt){
            int rem = n - tgt; // working length
            if(tgt>=1 && rem>=3){
                // x=1, y=rem-1: moves last rem-1 elements to front relative to working... no, global.
                doOp(tgt, n-1-tgt);
                // element was at n-1, now at n-tgt (= n-1 - tgt + 1... let me just refind)
                for(int i=tgt;i<n;i++) if(p[i]==tgt+1){pos=i;break;}
                if(pos!=tgt && pos+1+(n-1-pos)<n) doOp(pos+1, n-1-pos);
                for(int i=tgt;i<n;i++) if(p[i]==tgt+1){pos=i;break;}
                if(pos!=tgt && n-1-tgt>=2) doOp(tgt+1, n-1-tgt-1);
                for(int i=tgt;i<n;i++) if(p[i]==tgt+1){pos=i;break;}
            } else if(tgt==0){
                doOp(1,1);
            }
        }
    }
    printf("%d\n",(int)ops.size());
    for(auto&[x,y]:ops) printf("%d %d\n",x,y);
}
